//! Representation of a Dust function.
//!
//! Prototypes are generated by the compiler (specifically, the emitter) and are used by the virtual
//! machine to execute Dust functions within a program. Dust's prototypes are not self-contained,
//! instructions refer directly to the program's global constant pool and prototype list. This is a
//! key diversion from Lua's design (which is a major influence for Dust), in which each prototype
//! contains its own lists of constants and nested prototypes.
use std::{
    borrow::Borrow,
    collections::HashSet,
    fmt::{self, Debug, Display, Formatter},
    ops::Index,
    vec,
};

use rustc_hash::FxBuildHasher;
use serde::{Deserialize, Serialize};

use crate::{
    dust_type::DustType,
    instruction::{Address, Call, Instruction, MemoryKind, OperandType, Operation},
};

/// Compiled representation of a Dust function.
#[derive(Clone, Debug, Eq, PartialEq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct Prototype {
    pub(crate) instructions: Vec<Instruction>,
    pub(crate) call_arguments: Vec<(Address, OperandType)>,
    pub(crate) drops: Vec<u16>,

    pub(crate) return_type: DustType,

    pub(crate) register_count: u16,
}

impl Prototype {
    pub(crate) fn dummy() -> Self {
        Self {
            instructions: Vec::new(),
            call_arguments: Vec::new(),
            drops: Vec::new(),
            return_type: DustType::None,
            register_count: 0,
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct PrototypeList {
    prototypes: Vec<Prototype>,
}

impl PrototypeList {
    pub(crate) fn new() -> Self {
        Self {
            prototypes: Vec::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.prototypes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.prototypes.is_empty()
    }

    pub fn as_vec(&self) -> &Vec<Prototype> {
        &self.prototypes
    }

    pub fn as_slice(&self) -> &[Prototype] {
        &self.prototypes
    }

    pub fn iter(&self) -> impl Iterator<Item = &Prototype> {
        self.prototypes.iter()
    }

    pub fn reserve_slot(&mut self) -> PrototypeId {
        let id = PrototypeId(self.prototypes.len() as u16);

        self.prototypes.push(Prototype::dummy());

        id
    }

    pub fn set_slot(&mut self, id: PrototypeId, prototype: Prototype) {
        assert!(
            (id.0 as usize) < self.prototypes.len(),
            "Logic error: misuse of prototype ID {id}. When used correctly, prototype IDs are always\
            reserved before being set, so this should never happen.",
        );

        self.prototypes[id.0 as usize] = prototype;
    }

    // https://en.wikipedia.org/wiki/Tarjan's_strongly_connected_components_algorithm
    pub fn get_compile_info(&self) -> PrototypeCompileInfo {
        struct Tarjan<'a> {
            compile_order: Vec<PrototypeId>,
            edges: &'a [HashSet<PrototypeId, FxBuildHasher>],
            index_counter: usize,
            call_stack: Vec<PrototypeId>,
            on_stack: Vec<bool>,
            indices: Vec<usize>,
            lowlinks: Vec<usize>,
            scc_id: Vec<usize>,
            scc_count: usize,
        }

        impl Tarjan<'_> {
            fn visit(&mut self, current: PrototypeId) {
                let current_index = current.0 as usize;

                self.indices[current_index] = self.index_counter;
                self.lowlinks[current_index] = self.index_counter;
                self.index_counter += 1;
                self.on_stack[current_index] = true;

                self.call_stack.push(current);

                for neighbor in &self.edges[current_index] {
                    let neighbor_index = neighbor.0 as usize;
                    let index_is_empty = self.indices[neighbor_index] == usize::MAX;

                    if index_is_empty {
                        self.visit(*neighbor);

                        let lower_lowlink =
                            self.lowlinks[current_index].min(self.lowlinks[neighbor_index]);

                        self.lowlinks[current_index] = lower_lowlink;

                        continue;
                    }

                    let neighbor_on_stack = self.on_stack[neighbor_index];

                    if neighbor_on_stack {
                        let lower_index =
                            self.lowlinks[current_index].min(self.indices[neighbor_index]);

                        self.lowlinks[current_index] = lower_index;
                    }
                }

                if self.lowlinks[current_index] == self.indices[current_index] {
                    while let Some(top) = self.call_stack.pop() {
                        let top_index = top.0 as usize;

                        self.on_stack[top_index] = false;
                        self.scc_id[top_index] = self.scc_count;
                        self.compile_order.push(top);
                        if top_index == current_index {
                            break;
                        }
                    }
                    self.scc_count += 1;
                }
            }
        }

        let prototype_count = self.prototypes.len();
        let mut edges = vec![HashSet::default(); prototype_count];
        let mut argument_counts = vec![0; prototype_count];

        for (caller_index, prototype) in self.prototypes.iter().enumerate() {
            for instruction in &prototype.instructions {
                if instruction.operation() == Operation::CALL {
                    let Call {
                        callee,
                        argument_count,
                        ..
                    } = Call::from(instruction);

                    let callee_id = PrototypeId(callee.index);

                    edges[caller_index].insert(callee_id);
                    argument_counts[caller_index] = argument_count;
                }
            }
        }

        let mut tarjan = Tarjan {
            edges: &edges,
            index_counter: 0,
            call_stack: Vec::new(),
            on_stack: vec![false; prototype_count],
            indices: vec![usize::MAX; prototype_count],
            lowlinks: vec![usize::MAX; prototype_count],
            scc_id: vec![usize::MAX; prototype_count],
            scc_count: 0,
            compile_order: Vec::with_capacity(prototype_count),
        };

        tarjan.visit(PrototypeId::MAIN);

        let mut recursive_calls = HashSet::default();

        for (caller_index, callees) in edges.iter().enumerate() {
            for &callee in callees {
                let callee_index = callee.0 as usize;

                if tarjan.scc_id[caller_index] == tarjan.scc_id[callee_index] {
                    let caller = PrototypeId(caller_index as u16);

                    recursive_calls.insert((caller.0, callee.0));
                }
            }
        }

        PrototypeCompileInfo {
            compile_order: tarjan.compile_order,
            argument_counts,
            recursive_calls,
        }
    }
}

pub struct PrototypeCompileInfo {
    pub compile_order: Vec<PrototypeId>,
    pub argument_counts: Vec<u16>,
    pub recursive_calls: HashSet<(u16, u16), FxBuildHasher>,
}

impl Borrow<[Prototype]> for PrototypeList {
    fn borrow(&self) -> &[Prototype] {
        &self.prototypes
    }
}

impl Index<usize> for PrototypeList {
    type Output = Prototype;

    fn index(&self, index: usize) -> &Self::Output {
        &self.prototypes[index]
    }
}

impl Index<PrototypeId> for PrototypeList {
    type Output = Prototype;

    fn index(&self, index: PrototypeId) -> &Self::Output {
        &self.prototypes[index.0 as usize]
    }
}

impl IntoIterator for PrototypeList {
    type Item = Prototype;
    type IntoIter = vec::IntoIter<Prototype>;

    fn into_iter(self) -> Self::IntoIter {
        self.prototypes.into_iter()
    }
}

#[derive(Copy, Clone, Debug, Eq, PartialEq, PartialOrd, Ord, Hash)]
pub struct PrototypeId(#[cfg(test)] pub(crate) u16, #[cfg(not(test))] u16);

impl PrototypeId {
    pub(crate) const MAIN: Self = Self(0);

    pub fn from_address(address: Address) -> Option<Self> {
        if address.memory == MemoryKind::CONSTANT {
            Some(PrototypeId(address.index))
        } else {
            None
        }
    }

    pub fn index(self) -> u16 {
        self.0
    }

    pub fn index_usize(self) -> usize {
        self.0 as usize
    }
}

impl Display for PrototypeId {
    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
        write!(f, "proto_{}", self.0)
    }
}
